                    xs = sorted(list(set(pt[0] for pt in p)))
                    ys = sorted(list(set(pt[1] for pt in p)))

                    # Must have exactly 2 unique x and 2 unique y to form an axis-aligned rectangle
                    if len(xs) == 2 and len(ys) == 2:
                        x1, x2 = xs
                        y1, y2 = ys
                        corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}

                        # Check if all 4 corners exist in the input points
                        if all(c in [tuple(pt) for pt in points] for c in corners):
                            area = (x2 - x1) * (y2 - y1)
                            is_valid = True

                            # Check if any other point is inside or on the boundary
                            for px, py in points:
                                if (px, py) not in corners:
                                    if x1 <= px <= x2 and y1 <= py <= y2:
                                        is_valid = False
                                        break

                            if is_valid:
                                max_area = max(max_area, area)

