```python
from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # 因為是對稱結構，我們只需要處理一半的房子
    # 每一步考慮兩端對應的房子 (i 和 n-1-i)
    half = n // 2

    # dp[i][j] 表示前 i 對房子中，第 i 對最後使用的顏色是 j
    # 因為每對房子必須選兩個不同的顏色，且與上一對不同，
    # 我們用 dp[j] 代表「當前對子選了顏色 j 和 某個不等於 j 的顏色 k」的最小成本。
    # 但更簡單的方法是：對於每一對 (i, n-1-i)，我們枚舉這兩房子可能的顏色組合 (c1, c2)
    # 其中 c1 != c2，且 c1 != 上一對的顏色，c2 != 上一對的顏色。

    # 這裡使用 dp[color_left][color_right] 表示最後一對房子選用的顏色組合
    # 因為只有 3 種顏色，組合最多 3*2 = 6 種。
    # 我們用一個字典或二維陣列來存儲狀態：dp[(c1, c2)] = min_cost

    # 初始化第一對房子 (0, n-1)
    # dp[(c1, c2)] = cost[0][c1] + cost[n-1][c2] 其中 c1 != c2
    dp = {}
    for c1 in range(3):
        for c2 in range(3):
            if c1 != c2:
                dp[(c1, c2)] = cost[0][c1] + cost[n - 1][c2]

    # 從第 1 對到最後一對 (共 half 對)
    for i in range(1, half):
        new_dp = {}
        current_left_idx = i
        current_right_idx = n - 1 - i

        for c1 in range(3):
            for c2 in range(3):
                if c1 == c2: continue

                best_prev = float('inf')
                # 前一對的顏色為 (pc1, pc2)
                # 條件：c1 != pc1 且 c2 != pc2 且 pc1 != pc2
                for (pc1, pc2), val in dp.items():
                    if c1 != pc1 and c2 != pc2:
                        if val < best_prev:
                            best_prev = val

                if best_prev != float('inf'):
                    new_dp[(c1, c2)] = best_prev + cost[current_left_idx][c1] + cost[current_right_idx][c2]
        dp = new_dp

    return min(dp.values())
