from typing import List

def maxRemovals(source: str, pattern: str, targetIndices: List[int]) -> int:
    n = len(source)
    m = len(pattern)
    is_target = [False] * n
    for idx in targetIndices:
        is_target[idx] = True

    # dp[j] is the minimum number of elements from targetIndices 
    # used to form prefix pattern[:i] ending at index j.
    dp = [float('inf')] * n

    first_char = pattern[0]
    for j in range(n):
        if source[j] == first_char:
            dp[j] = 1 if is_target[j] else 0

    # Pre-calculate positions of each character to optimize the inner loop
    char_positions = {}
    for j, char in enumerate(source):
        if char not in char_positions:
            char_positions[char] = []
        char_positions[char].append(j)

    # Iterate through the pattern starting from the second character
    for i in range(1, m):
        next_dp = [float('inf')] * n
        char_to_match = pattern[i]

        # To compute next_dp[j], we need min(dp[k] for k < j) 
        # where source[j] == char_to_match.
        # We pre-calculate prefix minimums to do this in O(1) per position.
        prefix_min = [float('inf')] * (n + 1)
        curr_min = float('inf')
        for j in range(n):
            if dp[j] < curr_min:
                curr_min = dp[j]
            prefix_min[j+1] = curr_min

        # If the character doesn't exist in source, pattern cannot be a subsequence.
        # However, constraints guarantee it is.
        if char_to_match in char_positions:
            for j in char_positions[char_to_match]:
                prev_val = prefix_min[j]
                if prev_val != float('inf'):
                    next_dp[j] = prev_val + (1 if is_target[j] else 0)
        dp = next_dp

    # The answer is total target indices minus the minimum count used in any valid subsequence.
    return len(targetIndices) - min(dp)
