                    if day2_max.get(v, 0) < day2_max[u] * r:
                        day2_max[v] = day2_max[u] * r
                        changed = True
        if not changed: break

    # Also need to consider the inverse rates for Day 2 (converting back)
    # The problem says "each targetCurrency can be converted back... at a rate of 1/rate".
    # This means if pairs2 has [A, B] with rate R, we can do A -> B (R) or B -> A (1/R).
    graph2_full = {}
    for i in range(len(pairs2)):
        u, v = pairs2[i]
        r = rates2[i]
        if u not in graph2_full: graph2_full[u] = []
        graph2_full[u].append((v, r))
        if v not in graph2_full: graph2_full[v] = []
        graph2_full[v].append((u, 1.0 / r))

    # Re-calculate day2_max with full bi-directional edges for Day 2
    day2_max_full = day1_max.copy()
    for _ in range(len(all_currencies2) + 1):
        changed = False
        for u in graph2_full:
            if day2_max_full.get(u, 0) > 0:
                for v, r in graph2_full[u]:
                    if day2_max_full.get(v, 0) < day2_max_full[u] * r:
                        day2_max_full[v] = day2_max_full[u] * r
                        changed = True
        if not changed: break

    return max(day2_max_full.get(initialCurrency, 1.0), 1.0)

